require("handlebars");
var I18nHelper = class {
	helperFunc(context, i18n_key) {
		if (i18n_engine_default.exists(i18n_key)) return i18n_engine_default.translate(i18n_key.toLowerCase());
		else return i18n_key;
	}
};
//#endregion
//#region src/app/engines/html-engine-helpers/if-string.helper.ts
var IfStringHelper = class {
	helperFunc(context, a, options) {
		if (typeof a === "string") return options.fn(context);
		return options.inverse(context);
	}
};
//#endregion
//#region src/app/engines/html-engine-helpers/indexable-signature.helper.ts
var IndexableSignatureHelper = class {
	helperFunc(context, method) {
		const args = method.args.map((arg) => `${arg.name}: ${arg.type}`).join(", ");
		if (method.name) return `${method.name}[${args}]`;
		else return `[${args}]`;
	}
};
//#endregion
//#region src/app/engines/html-engine-helpers/is-initial-tab.helper.ts
var IsInitialTabHelper = class {
	helperFunc(context, tabs, tabId, options) {
		return tabs[0].id === tabId ? options.fn(context) : options.inverse(context);
	}
};
//#endregion
//#region src/app/engines/html-engine-helpers/is-not-toggle.helper.ts
var IsNotToggleHelper = class {
	constructor() {}
	helperFunc(context, type, options) {
		let result = configuration_default.mainData.toggleMenuItems.indexOf(type);
		if (configuration_default.mainData.toggleMenuItems.indexOf("all") !== -1) return options.inverse(context);
		else if (result !== -1) return options.fn(context);
		else return options.inverse(context);
	}
};
//#endregion
//#region src/app/engines/html-engine-helpers/is-tab-enabled.helper.ts
var IsTabEnabledHelper = class {
	helperFunc(context, tabs, tabId, options) {
		return -1 !== findIndex(tabs, { id: tabId }) ? options.fn(context) : options.inverse(context);
	}
};
