					if (!element.methods) element.methods = [];
					let cla = {
						filePath: element.file,
						type,
						linktype,
						name: element.name
					};
					let totalStatementDocumented = 0;
					let totalStatements = element.properties.length + element.methods.length + 1;
					if (element.constructorObj) {
						totalStatements += 1;
						if (element.constructorObj && element.constructorObj.description && element.constructorObj.description !== "") totalStatementDocumented += 1;
					}
