	handleTemplateurl(component) {
		const dirname = path.dirname(component.file);
		const templatePath = path.resolve(dirname + path.sep + component.templateUrl);
		if (!file_engine_default.existsSync(templatePath)) {
			const err = `Cannot read template for ${component.name}`;
			require_logger.logger.error(err);
			return new Promise((resolve, reject) => {});
		}
		return file_engine_default.get(templatePath).then((data) => {
			component.templateData = data;
			component.templateVariables = ComponentHelper.getTemplateVariablesFromTemplate(data);
		}, (err) => {
			require_logger.logger.error(err);
			return Promise.reject("");
		});
	}
	handleStyles(component) {
		const styles = component.styles;
		component.stylesData = "";
		return new Promise((resolveStyles, rejectStyles) => {
			styles.forEach((style) => {
				component.stylesData = component.stylesData + style + "\n";
			});
			resolveStyles(true);
		});
	}
	handleStyleurls(component) {
		const dirname = path.dirname(component.file);
		const styleDataPromise = component.styleUrls.map((styleUrl) => {
			const stylePath = path.resolve(dirname + path.sep + styleUrl);
			if (!file_engine_default.existsSync(stylePath)) {
				const err = `Cannot read style url ${stylePath} for ${component.name}`;
				require_logger.logger.error(err);
				return Promise.resolve(null);
			}
			return new Promise((resolve, reject) => {
				file_engine_default.get(stylePath).then((data) => {
					resolve({
						data,
						styleUrl
					});
				});
			});
		});
		return Promise.all(styleDataPromise).then((data) => component.styleUrlsData = data.filter((item) => item !== null), (err) => {
			require_logger.logger.error(err);
			return Promise.reject("");
		});
	}
	getRelationships(dependency) {
		if (!dependency?.name) return {
			incoming: [],
			outgoing: []
		};
		return dependencies_engine_default.getRelationships(dependency);
	}
	hasApiSections(dependency) {
		if (!dependency) return false;
		return [
			dependency.constructorObj,
			dependency.inputsClass,
			dependency.outputsClass,
			dependency.hostBindings,
			dependency.hostListeners,
			dependency.methodsClass,
			dependency.propertiesClass,
			dependency.accessors,
			dependency.properties,
			dependency.methods,
			dependency.indexSignatures
		].some((entry) => {
			if (!entry) return false;
			if (Array.isArray(entry)) return entry.length > 0;
			return true;
		});
	}
	getNavTabs(dependency) {
		let navTabConfig = configuration_default.mainData.navTabConfig;
		const hasCustomNavTabConfig = navTabConfig.length !== 0;
		navTabConfig = navTabConfig.length === 0 ? cloneDeep(COMPODOC_CONSTANTS.navTabDefinitions) : navTabConfig;
		const matchDepType = (depType) => {
			return depType === "all" || depType === dependency.type;
		};
		let navTabs = [];
		forEach(navTabConfig, (customTab) => {
			const navTab = find(COMPODOC_CONSTANTS.navTabDefinitions, { id: customTab.id });
			if (!navTab) throw new Error(`Invalid tab ID '${customTab.id}' specified in tab configuration`);
			navTab.label = customTab.label;
			if (hasCustomNavTabConfig) navTab.custom = true;
			if (-1 === findIndex(navTab.depTypes, matchDepType)) return;
			if (customTab.id === "tree" && configuration_default.mainData.disableDomTree) return;
			if (customTab.id === "source" && configuration_default.mainData.disableSourceCode) return;
			if (customTab.id === "templateData" && configuration_default.mainData.disableTemplateTab) return;
			if (customTab.id === "styleData" && configuration_default.mainData.disableStyleTab) return;
			if (customTab.id === "readme" && !dependency.readme) return;
			if (customTab.id === "example" && !dependency.exampleUrls) return;
			if (customTab.id === "templateData" && (!dependency.templateUrl || dependency.templateUrl.length === 0)) return;
			if (customTab.id === "styleData" && (!dependency.styleUrls || dependency.styleUrls.length === 0) && (!dependency.styles || dependency.styles.length === 0)) return;
			if (customTab.id === "api" && !this.hasApiSections(dependency)) return;
			navTabs.push(navTab);
		});
		if (navTabs.length === 0) throw new Error(`No valid navigation tabs have been defined for dependency type '${dependency.type}'. Specify \
at least one config for the 'info' or 'source' tab in --navTabConfig.`);
		return navTabs;
	}
